import { SUPPORTED_PRIMES, SUPPORTED_ODD_LIMITS } from '../constants';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

// Map Primes/Identities to Ratios
// Includes composites (9, 15) for axis support
const PRIME_RATIOS: Record<number, Fraction> = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  9: new Fraction(9, 8),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
  15: new Fraction(15, 8),
  17: new Fraction(17, 16),
  19: new Fraction(19, 16)
};

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      // Normalize origin coords to match supported primes length
      const safeOriginCoords = [...origin.coords];
      while (safeOriginCoords.length < SUPPORTED_PRIMES.length) safeOriginCoords.push(0);

      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = new Fraction(1, 1);
      SUPPORTED_PRIMES.forEach((p, idx) => {
          const val = safeOriginCoords[idx];
          const pRat = PRIME_RATIOS[p];
          if (pRat) {
              for(let i=0; i<Math.abs(val); i++) {
                  originFrac = val > 0 ? originFrac.mul(pRat).normalize() : originFrac.mul(new Fraction(pRat.d, pRat.n)).normalize();
              }
          }
      });

      localQueue.push({ coords: safeOriginCoords, ratio: originFrac });
      const visitedLocal = new Set<string>([safeOriginCoords.join(',')]);

      const MAX_LOCAL_NODES = 1200;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(
                      current.coords, 
                      absoluteRatio, 
                      settings.latticeAspectRatio, 
                      settings.layoutApproach
                  );

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          SUPPORTED_PRIMES.forEach((prime, idx) => {
              const depthLimit = settings.limitDepths[prime] || 0;
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  if (Math.abs(nextCoords[idx] - safeOriginCoords[idx]) > depthLimit) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime];
                      const nextFrac = dir === 1 ? current.ratio.mul(pRat).normalize() : current.ratio.mul(new Fraction(pRat.d, pRat.n)).normalize();

                      const compLimit = (settings.limitComplexities && settings.limitComplexities[prime]) ? settings.limitComplexities[prime] : 1000;
                      if (nextFrac.n <= compLimit && nextFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  nodes.forEach(node => {
      SUPPORTED_PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const target = nodesMap.get(`${coordKey}:${o}`);
              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const pRat = PRIME_RATIOS[prime];
                  const test = ratio / (pRat.n / pRat.d);
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      });
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 * Responds to SUPPORTED_ODD_LIMITS for consistency.
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    // Strict Filtering: Only include identities explicitly enabled (not hidden)
    const activeIdentities = SUPPORTED_ODD_LIMITS.filter(id => id === 1 || !settings.hiddenLimits.includes(id));
    const N = activeIdentities.length;

    // Scale factor to ensure nodes are visually separated
    const diamondSpacing = 200; 

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            // Stable ID based on Identities
            const id = `diamond-${idOton}-${idUton}`;

            // Layout indices rotated 45 degrees
            const x = ((o + u) - (N - 1)) * diamondSpacing;
            const y = (u - o) * diamondSpacing;

            nodes.push({
                id,
                coords: [o, u, 0, 0, 0], 
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x,
                y: y,
                limitTop: getMaxPrime(frac.n),
                limitBottom: getMaxPrime(frac.d),
                maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import { AppSettings, LayoutApproach } from '../types';

export const PITCH_SCALE = 200; // Pixels per octave (Base Scale)

// Basis vectors for the lattice projection (X-axis contribution per prime index)
// Indices correspond to SUPPORTED_PRIMES: [3, 5, 7, 9, 11, 13, 15, 17, 19]
export const BASIS_VECTORS_X = [
    100, // 3
    30,  // 5
    20,  // 7
    200, // 9 (2 * Vector3)
    -20, // 11
    -30, // 13
    130, // 15 (Vector3 + Vector5)
    40,  // 17
    -40  // 19
];

/**
 * Projects harmonic coordinates into 2D screen space based on selected layout approach.
 */
export const projectCoordinates = (
    coords: number[], 
    ratio: number, 
    aspectRatio: number,
    approach: LayoutApproach = 'lattice'
): { x: number, y: number } => {
    let x = 0;
    let y = 0;

    const spacing = 140; 

    // Helper to get coordinate for a specific prime index safely
    // 0=3, 1=5, 2=7, 3=9, 4=11, 5=13, 6=15, 7=17, 8=19
    const getC = (idx: number) => coords[idx] || 0;

    if (approach === 'lattice') {
        for(let i = 0; i < coords.length; i++) {
            if (i < BASIS_VECTORS_X.length) {
                x += coords[i] * BASIS_VECTORS_X[i];
            }
        }
        x = x * (1.0 / aspectRatio);
        y = -(Math.log2(ratio) * PITCH_SCALE);
    } 
    else if (approach === 'diamond') {
        /**
         * Partch Tonality Diamond:
         * coords[0] = Otonality Index, coords[1] = Utonality Index
         */
        x = coords[0] * spacing;
        y = coords[1] * spacing;
    }
    else if (approach === 'row') {
        x = Math.log2(ratio) * 1200; 

        // Simple heuristic for Y stacking based on complexity
        // We sum absolute values of all higher prime coordinates
        let complexity = 0;
        for(let i = 0; i < coords.length; i++) complexity += Math.abs(coords[i]) * (i + 1);

        const dir = complexity % 2 === 0 ? 1 : -1;
        y = dir * (complexity * spacing * 0.4);
    }
    else if (approach === 'honeycomb') {
        // Hex Layout primarily uses 3 (Index 0) and 5 (Index 1) axes
        const hexUnit = spacing * 0.9;
        const p3 = getC(0);
        const p5 = getC(1);
        const p7 = getC(2);

        x = (p3 + p5 * 0.5 + p7 * -0.5) * hexUnit;
        y = (p5 * 0.866 + p7 * 0.866) * hexUnit;

        // Add subtle offsets for higher primes to avoid total overlap
        for(let i = 3; i < coords.length; i++) {
            x += (coords[i] * 10);
            y += (coords[i] * 10);
        }

        x = x * (1.0 / aspectRatio);
    }

    return { x, y };
};

export const getPitchRatioFromScreenDelta = (
    deltaY: number, 
    spacingScale: number
): number => {
    const effectiveScale = PITCH_SCALE * spacingScale;
    return Math.pow(2, -deltaY / effectiveScale);
};

export const getRainbowPeriod = (spacingScale: number): number => {
    return PITCH_SCALE * spacingScale;
};

import React from 'react';
import { AppSettings, XYPos } from '../types';
import { useDragManager } from '../hooks/useDragManager';
import { SUPPORTED_ODD_LIMITS } from '../constants';

interface Props {
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;
  isShortScreen?: boolean;
}

const LimitLayerControls: React.FC<Props> = ({ settings, updateSettings, draggingId, setDraggingId, uiScale = 1.0, isShortScreen = false }) => {
  const { uiUnlocked, uiPositions } = settings;

  // Size increased by 1/3: 56 * 1.33 = 75, 28 * 1.33 = 37
  const buttonSize = 75 * uiScale; 
  const iconSize = 37 * uiScale; 

  const isVisible = (limit: number) => {
    // 1-Limit is always visible
    if (limit === 1) return true;
    return !settings.hiddenLimits.includes(limit);
  };

  const toggleVisibility = (limit: number) => {
    // Prevent hiding 1-Limit
    if (limit === 1) return;

    const isHidden = settings.hiddenLimits.includes(limit);
    let newHidden = [...settings.hiddenLimits];
    if (isHidden) {
      newHidden = newHidden.filter(l => l !== limit);
    } else {
      newHidden.push(limit);
    }
    updateSettings({ ...settings, hiddenLimits: newHidden });
  };

  const bringToFront = (limit: number) => {
    const newOrder = settings.layerOrder.filter(l => l !== limit);
    newOrder.push(limit);
    updateSettings({ ...settings, layerOrder: newOrder });
  };

  // Wrapper for updateSettings to match signature expected by hook
  const handlePositionUpdate = (id: string, pos: XYPos) => {
      updateSettings({ 
          ...settings, 
          uiPositions: { 
              ...settings.uiPositions, 
              layers: pos 
          } 
      });
  };

  const handleDrag = useDragManager(
      uiUnlocked,
      draggingId,
      setDraggingId,
      handlePositionUpdate,
      uiPositions as unknown as Record<string, XYPos> // Cast safe here as we access by key
  );

  return (
    <div 
        className={`absolute flex flex-col gap-1 z-[140] bg-slate-900/50 p-2 rounded-xl backdrop-blur-sm border border-slate-700/50 ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ left: uiPositions.layers.x, top: uiPositions.layers.y, touchAction: 'none' }}
        onPointerDown={(e) => handleDrag(e, 'layers')}
    >
      {SUPPORTED_ODD_LIMITS.map(limit => {
        const visible = isVisible(limit);
        const color = settings.colors[limit];
        const isTop = settings.layerOrder[settings.layerOrder.length - 1] === limit;
        const isLocked = limit === 1;

        return (
          <div key={limit} className="flex items-center gap-2 group">
            {/* Visibility Toggle */}
            <button 
              onClick={(e) => { e.stopPropagation(); !uiUnlocked && toggleVisibility(limit); }}
              disabled={isLocked}
              className={`flex items-center justify-center rounded transition-colors ${visible ? (isLocked ? 'text-slate-500 cursor-default opacity-50' : 'text-white') : 'text-slate-600'} hover:bg-white/10 ${uiUnlocked ? 'pointer-events-none' : ''}`}
              style={{ width: iconSize, height: iconSize }}
              onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
            >
               {visible ? (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-full h-full p-0.5">
                   <path d="M10 12.5a2.5 2.5 0 100-5 2.5 2.5 0 000 5z" />
                   <path fillRule="evenodd" d="M.664 10.59a1.651 1.651 0 010-1.186A10.004 10.004 0 0110 3c4.257 0 8.201 2.372 9.336 6.41.147.527.147 1.074 0 1.601C18.201 14.628 14.257 17 10 17c-4.257 0-8.201-2.372-9.336-6.41zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd" />
                 </svg>
               ) : (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-full h-full p-0.5">
                   <path fillRule="evenodd" d="M3.28 2.22a.75.75 0 00-1.06 1.06l14.5 14.5a.75.75 0 101.06-1.06l-1.745-1.745A10.029 10.029 0 0018 10c-1.135-4.038-5.079-6.41-9.336-6.41a9.982 9.982 0 00-4.636 1.135L3.28 2.22zm12.98 12.98l-3.212-3.212a3.003 3.003 0 00-4.244-4.244L5.68 4.62A11.967 11.967 0 00.664 9.41a1.651 1.651 0 010 1.18c1.135 4.038 5.079 6.41 9.336 6.41 2.053 0 4.008-.584 5.688-1.613l.572.572z" clipRule="evenodd" />
                   <path d="M10.983 7.796a1.5 1.5 0 012.122 2.122l-2.122-2.122z" />
                 </svg>
               )}
            </button>

            {/* Color/Select Layer Button */}
            <button 
              onClick={(e) => { e.stopPropagation(); !uiUnlocked && bringToFront(limit); }}
              className={`rounded-lg shadow-md border-2 transition-all transform active:scale-95 flex items-center justify-center font-bold text-shadow ${uiUnlocked ? 'pointer-events-none' : ''}`}
              style={{ 
                width: buttonSize, 
                height: buttonSize,
                fontSize: 16 * uiScale,
                backgroundColor: color, 
                borderColor: isTop ? 'white' : 'transparent',
                boxShadow: isTop ? '0 0 10px rgba(255,255,255,0.5)' : 'none',
                opacity: visible ? 1 : 0.2
              }}
              onPointerDown={(e) => !uiUnlocked && e.stopPropagation()}
            >
              {limit}
            </button>
          </div>
        );
      })}
    </div>
  );
};

