// Import only for reference in comments/types, logic remains index-aligned
import { LATTICE_GENERATION_PRIMES } from '../constants';

export const PITCH_SCALE = 200; // Pixels per octave (Base Scale)

// Basis vectors for the lattice projection (X-axis contribution per prime index)
// Indices correspond STRICTLY to LATTICE_GENERATION_PRIMES: [3, 5, 7, 11, 13, 17, 19]
// STRATEGY: Alternating Handedness "V-Shape"
// 3 (Fifths) moves Right. 5 (Thirds) moves Left.
// This maximizes the horizontal distance between comma-related nodes (e.g. 81/80).
export const BASIS_VECTORS_X = [
    120,  // 3 (Index 0) - Strong Right
    -90,  // 5 (Index 1) - Strong Left
    60,   // 7 (Index 2) - Medium Right
    -45,  // 11 (Index 3) - Medium Left
    30,   // 13 (Index 4) - Small Right
    -20,  // 17 (Index 5) - Small Left
    15    // 19 (Index 6) - Tiny Right
];

/**
 * Projects harmonic coordinates into 2D screen space based on selected layout approach.
 */
export const projectCoordinates = (
    coords: number[], 
    ratio: number, 
    aspectRatio: number,
    approach: LayoutApproach = 'lattice'
): { x: number, y: number } => {
    let x = 0;
    let y = 0;

    const spacing = 140; 

    // Helper to get coordinate for a specific prime index safely
    const getC = (idx: number) => coords[idx] || 0;

    if (approach === 'lattice') {
        for(let i = 0; i < coords.length; i++) {
            if (i < BASIS_VECTORS_X.length) {
                x += coords[i] * BASIS_VECTORS_X[i];
            }
        }
        // Apply Aspect Ratio Correction to X
        x = x * (1.0 / aspectRatio);

        // Y is strictly Pitch Height
        y = -(Math.log2(ratio) * PITCH_SCALE);
    } 
    else if (approach === 'diamond') {
        /**
         * Partch Tonality Diamond:
         * coords[0] = Otonality Index, coords[1] = Utonality Index
         */
        x = coords[0] * spacing;
        y = coords[1] * spacing;
    }
    else if (approach === 'row') {
        x = Math.log2(ratio) * 1200; 

        // Simple heuristic for Y stacking based on complexity
        let complexity = 0;
        for(let i = 0; i < coords.length; i++) complexity += Math.abs(coords[i]) * (i + 1);

        const dir = complexity % 2 === 0 ? 1 : -1;
        y = dir * (complexity * spacing * 0.4);
    }
    else if (approach === 'honeycomb') {
        // Hex Layout primarily uses 3 (Index 0) and 5 (Index 1) axes
        const hexUnit = spacing * 0.9;
        const p3 = getC(0);
        const p5 = getC(1);
        const p7 = getC(2);

        // Hexagonal Transform
        x = (p3 + p5 * 0.5 + p7 * -0.5) * hexUnit;
        y = (p5 * 0.866 + p7 * 0.866) * hexUnit;

        // Add subtle offsets for higher primes to avoid total overlap
        for(let i = 3; i < coords.length; i++) {
            x += (coords[i] * 10);
            y += (coords[i] * 10);
        }

        x = x * (1.0 / aspectRatio);
    }

    return { x, y };
};

export const getPitchRatioFromScreenDelta = (
    deltaY: number, 
    spacingScale: number
): number => {
    const effectiveScale = PITCH_SCALE * spacingScale;
    return Math.pow(2, -deltaY / effectiveScale);
};

export const getRainbowPeriod = (spacingScale: number): number => {
    return PITCH_SCALE * spacingScale;
};

